// --- Cache version check -------------------------------------------------
const VERSION_FILE = "./version.json";
const VERSION_KEY = "app_version";

async function checkAppVersion() {
    try {
        const res = await fetch(VERSION_FILE, {
            method: "GET",
            cache: "no-store"
        });
        if (!res.ok) return;
        const data = await res.json();
        const remoteVersion = String(data.version || "");
        const localVersion = sessionStorage.getItem(VERSION_KEY) || "";
        if (remoteVersion && remoteVersion !== localVersion) {
            sessionStorage.setItem(VERSION_KEY, remoteVersion);
            // Hard-reload the DOCUMENT with cache-busting query params so a
            // stale index.html (and its stale app file) can never be reused.
            // sessionStorage persists across the reload, so this runs once.
            try {
                const u = new URL(location.href);
                u.searchParams.set("_rv", remoteVersion);
                u.searchParams.set("_t", String(Date.now()));
                location.replace(u.toString());
            } catch (_) {
                location.reload(true);
            }
        } else if (!localVersion && remoteVersion) {
            sessionStorage.setItem(VERSION_KEY, remoteVersion);
        }
    } catch (_) {
        // offline or blocked Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В Р Р‹Р РЋРЎв„ў skip version check
    }
}
checkAppVersion();

