function escapeHtml(s) {
    return String(s).replace(
        /[&<>"']/g,
        (c) =>
        ({
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;"
        })[
            c
        ],
    );
}
