function imgProxyUrl(u) {
    const t = String(u).trim();
    if (/^data:/i.test(t)) return t;
    if (/^https?:\/\//i.test(t)) {
        try {
            return FN_BASE + "/img-proxy?u=" + encodeURIComponent(t);
        } catch (_) {
            return t;
        }
    }
    return "#";
}
