const THEME_PRESETS = {
    dark: {},
    light: {},
    midnight: {},
    aurora: {},
    sunset: {},
    cyber: {},
    neon: {},
    lava: {},
    ocean: {},
    monochrome: {},
    hacker: {},
    candy: {},
    nord: {},
    synthwave: {},
    catppuccin: {},
};

function applyTheme(t) {
    document.documentElement.setAttribute("data-theme", t || "dark");
    const grid = document.getElementById("themeGrid");
    if (grid) {
        aiHubQueryAll(grid, ".theme-card").forEach((c) => {
            c.classList.toggle("active", c.dataset.themeVal === t);
        });
    }
    const editor = document.getElementById("customThemeEditor");
    if (editor) editor.style.display = t === "custom" ? "flex" : "none";
    try {
        localStorage.setItem("theme", t || "dark");
    } catch (e) {}
}
let theme = "dark";
try {
    const saved = localStorage.getItem("theme");
    if (
        saved && [
            "dark",
            "light",
            "midnight",
            "aurora",
            "sunset",
            "cyber",
            "neon",
            "lava",
            "ocean",
            "monochrome",
            "hacker",
            "candy",
            "nord",
            "synthwave",
            "catppuccin",
            "custom",
        ].includes(saved)
    ) {
        theme = saved;
    } else if (saved) {
        theme = saved;
    } else if (
        window.matchMedia &&
        window.matchMedia("(prefers-color-scheme: light)").matches
    ) {
        theme = "light";
    }
    } catch (e) {}
applyTheme(theme);

function saveThemeToBackend(t) {
    try {
        const payload = Object.assign(authBody(), {
            theme: t
        });
        fetch(FN_BASE + "/settings", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(payload),
        }).catch(() => {});
    } catch (e) {}
}

document.getElementById("themeGrid").addEventListener("click", (e) => {
    vibClick();
    const card = e.target.closest(".theme-card");
    if (!card) return;
    const t = card.dataset.themeVal;
    if (!t) return;
    theme = t;
    applyTheme(t);
    saveThemeToBackend(t);
    if (t === "custom") loadCustomThemeEditor();
});

