// --- Message rendering -------------------------------------------------
function addMessage(role, html, stats, scroll) {
    const el = document.createElement("div");
    el.className = "msg md " + role;
    el.innerHTML = html;
    if (stats) {
        const s = document.createElement("div");
        s.className = "stats";
        s.textContent = stats;
        el.appendChild(s);
    }
    box.appendChild(el);
    if (role === "bot") addCodeCopy(el);
    if (scroll !== false) box.scrollTop = box.scrollHeight;
    updateEmptyState();
    return el;
}

function addCodeCopy(root) {
    aiHubQueryAll(root, "pre").forEach((pre) => {
        if (pre.parentElement && pre.parentElement.classList.contains("code-wrap"))
            return;
        const wrap = document.createElement("div");
        wrap.className = "code-wrap";
        pre.parentNode.insertBefore(wrap, pre);
        wrap.appendChild(pre);
        const btn = document.createElement("button");
        btn.className = "code-copy";
        btn.innerHTML = "<i data-lucide='clipboard-list' class='icon'></i>";
        if (window.lucide) lucide.createIcons();
        btn.title = "Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р Р†Р вЂљРЎвЂєР РЋРЎвЂєР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂєР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р Р†Р вЂљРЎСљР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂєР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В Р Р‹Р Р†РІР‚С›РЎС›Р В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В°";
        btn.addEventListener("click", () => {
            const code = pre.querySelector("code");
            const txt = code ? code.innerText : pre.innerText;
            navigator.clipboard
                .writeText(txt)
                .then(() => {
                    btn.innerHTML = "<i data-lucide='check' class='icon'></i>";
                    setTimeout(() => (btn.innerHTML = "<i data-lucide='clipboard-list' class='icon'></i>"), 1200);
                })
                .catch(() => {});
        });
        wrap.appendChild(btn);
    });
}

