const lb = $("#lightbox");
const lbImg = $("#lb_img");
let lbSrc = "";

function openLightbox(src) {
    if (!src) return;
    lbSrc = src;
    lbImg.src = src;
    lb.classList.add("open");
}

function closeLightbox() {
    lb.classList.remove("open");
    lbImg.src = "";
    lbSrc = "";
}
