// --- Context menu (copy / reply / delete) --------------------------
const ctxMenu = $("#ctxMenu");
let ctxMsgEl = null;
let ctxPressStart = 0;
let ctxPressStartSel = "";
let isOpenContextMenu = false;
let ctxStartX = 0;
let ctxStartY = 0;
let ctxMoved = false;

function hideCtx() {
    ctxMenu.style.display = "none";
    ctxMsgEl = null;
    isOpenContextMenu = false;
    ctxMoved = false;
}

function showCtx(x, y, msgEl) {
    if (isOpenContextMenu) return;
    ctxMsgEl = msgEl;
    ctxMenu.style.display = "flex";
    isOpenContextMenu = true;
    const r = ctxMenu.getBoundingClientRect();
    const w = window.innerWidth,
        h = window.innerHeight;
    ctxMenu.style.left = Math.min(x, w - 200) + "px";
    ctxMenu.style.top = Math.min(y, h - 160) + "px";
}
document.addEventListener("pointerdown", (e) => {
    if (!isOpenContextMenu) return;
    if (ctxMenu.contains(e.target)) return;
    hideCtx();
});
document.addEventListener("click", (e) => {
    if (!ctxMenu.contains(e.target)) hideCtx();
});
document.addEventListener("contextmenu", (e) => {
    const msg = e.target.closest(".msg");
    if (!msg) return;
    if (window.getSelection().toString().trim().length > 0) return;
    e.preventDefault();
    showCtx(e.clientX, e.clientY, msg);
});
box.addEventListener("pointerdown", (e) => {
    const msg = e.target.closest(".msg");
    if (!msg) return;
    const inner = e.target.closest("button, a, code, pre");
    if (inner) return;
    ctxPressStart = Date.now();
    ctxPressStartSel = window.getSelection().toString();
    ctxStartX = e.clientX;
    ctxStartY = e.clientY;
    ctxMoved = false;
});
box.addEventListener("pointermove", (e) => {
    if (!ctxPressStart) return;
    const dx = Math.abs(e.clientX - ctxStartX);
    const dy = Math.abs(e.clientY - ctxStartY);
    if (dx > 8 || dy > 8) ctxMoved = true;
});
box.addEventListener("pointerup", (e) => {
    const msg = e.target.closest(".msg");
    if (!msg) return;
    const inner = e.target.closest("button, a, code, pre");
    if (inner) return;
    if (ctxMoved) {
        ctxPressStart = 0;
        ctxPressStartSel = "";
        return;
    }
    const pressDuration = Date.now() - ctxPressStart;
    const selectionChanged = window.getSelection().toString().trim().length > 0 && window.getSelection().toString() !== ctxPressStartSel;
    if (isOpenContextMenu) {
        hideCtx();
        ctxPressStart = 0;
        ctxPressStartSel = "";
        return;
    }
    if (pressDuration < 200 && !selectionChanged && ctxPressStart > 0) {
        showCtx(e.clientX, e.clientY, msg);
    }
    ctxPressStart = 0;
    ctxPressStartSel = "";
});
ctxMenu.addEventListener("click", (e) => {
    const btn = e.target.closest("button");
    if (!btn || !ctxMsgEl) return;
    const act = btn.dataset.act;
    if (act === "copy") {
        const text = ctxMsgEl.innerText || ctxMsgEl.textContent;
        navigator.clipboard
            .writeText(text.trim())
            .then(() => toast("Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћвЂ“Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎС™Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂєР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р Р†Р вЂљРЎСљР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂєР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В¦Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂє", "ok"))
            .catch(() => {});
    } else if (act === "reply") {
        const text = (
            ctxMsgEl.querySelector(".md") ?
            ctxMsgEl.querySelector(".md").innerText :
            ctxMsgEl.innerText || ""
        ).trim();
        if (text) {
            $("#input").value = "> " + text.split("\n").join("\n> ") + "\n";
            $("#input").focus();
        }
    } else if (act === "regen") {
        let prev = ctxMsgEl.previousElementSibling;
        while (prev && !prev.classList.contains("user")) {
            prev = prev.previousElementSibling;
        }
        const text = prev ? (prev.innerText || prev.textContent).trim() : lastUserMessage;
        if (text) {
            $("#input").value = text;
            $("#bar").dispatchEvent(new Event("submit"));
        }
    } else if (act === "delete") {
        ctxMsgEl.remove();
        updateEmptyState();
        toast("Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р Р†Р вЂљРЎв„ўР вЂ™Р’В¬Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р РЋРЎвЂєР В Р вЂ Р В РІР‚С™Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В»Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В¦Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂє", "ok");
    }
    hideCtx();
});
