function clearSearchHighlight() {
    aiHubQueryAll(box, ".search-highlight-frame")
        .forEach((el) => el.classList.remove("search-highlight-frame"));
    aiHubQueryAll(box, ".search-highlight-term").forEach((el) => {
        const parent = el.parentNode;
        if (parent) {
            parent.replaceChild(document.createTextNode(el.textContent), el);
            parent.normalize();
        }
    });
    box.classList.remove("search-faded");
}

function highlightTermsInMsg(msgEl, term) {
    if (!term || !msgEl) return;
    const md = msgEl.querySelector(".md");
    if (!md) return;
    const terms = term.split(/\s+/).filter(Boolean);
    if (!terms.length) return;
    const regex = new RegExp(`(${terms.map(escRegex).join("|")})`, "gi");

    // Safe highlighting using TreeWalker - never converts text to HTML
    const walker = document.createTreeWalker(md, NodeFilter.SHOW_TEXT, null, false);
    const textNodes = [];
    let node;
    while ((node = walker.nextNode())) {
        if (node.textContent.match(regex)) {
            textNodes.push(node);
        }
    }
    textNodes.forEach((textNode) => {
        const text = textNode.textContent;
        const parent = textNode.parentNode;
        let lastIndex = 0;
        const fragment = document.createDocumentFragment();
        let match;
        while ((match = regex.exec(text)) !== null) {
            const matchIndex = match.index;
            if (matchIndex > lastIndex) {
                fragment.appendChild(document.createTextNode(text.slice(lastIndex, matchIndex)));
            }
            const span = document.createElement("span");
            span.className = "search-highlight-term";
            span.textContent = match[1];
            fragment.appendChild(span);
            lastIndex = matchIndex + match[0].length;
        }
        if (lastIndex < text.length) {
            fragment.appendChild(document.createTextNode(text.slice(lastIndex)));
        }
        parent.replaceChild(fragment, textNode);
    });
}

function escRegex(s) {
    return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
box.addEventListener("scroll", () => {
    userAtBottom = box.scrollTop + box.clientHeight >= box.scrollHeight - 60;
    if (userAtBottom) {
        box.classList.remove("search-faded");
    } else {
        box.classList.add("search-faded");
    }
});

